def transform(grid):
    """Fill the 6-masked cells using the image's diagonal and 32x32-crop symmetries."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            orbit = set()
            for a, b in ((r, c), (c, r)):
                for rr in (a, 31 - a):
                    for cc in (b, 31 - b):
                        if 0 <= rr < h and 0 <= cc < w:
                            orbit.add((rr, cc))
            known = [grid[rr][cc] for rr, cc in orbit if grid[rr][cc] != 6]
            if not known:
                raise ValueError(f"cannot infer masked cell {(r, c)}")
            out[r][c] = max(set(known), key=known.count)
    return out
